/**
 * @name Unsafe file open with user-controlled path
 * @description Opening files with user-controlled paths without validation
 * @kind path-problem
 * @problem.severity warning
 * @id py/pathspec-unsafe-open
 * @tags security
 *        external/cwe/cwe-22
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module UnsafeOpenConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::ParameterNode param | source = param)
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    )
  }
}

module UnsafeOpenFlow = TaintTracking::Global<UnsafeOpenConfig>;
import UnsafeOpenFlow::PathGraph

from UnsafeOpenFlow::PathNode source, UnsafeOpenFlow::PathNode sink
where UnsafeOpenFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "File open with path from $@.", source.getNode(), "user input"
